import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

// Hardcoded per project requirement (user-owned key, free Groq tier).
export const GROQ_API_KEY =
  process.env.GROQ_API_KEY ??
  "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";
export const MODEL = "groq/compound";
export const SUBAGENT_MODEL = "groq/compound-mini";
export const API_URL = "https://api.groq.com/openai/v1/chat/completions";

export const VERSION = "1.0.0";

export type Effort = "low" | "medium" | "high" | "max";

export const EFFORT_LEVELS: Record<Effort, { maxIterations: number; hint: string }> = {
  low: {
    maxIterations: 6,
    hint: "Work quickly. Prefer the most direct path. Skip optional verification.",
  },
  medium: {
    maxIterations: 14,
    hint: "Balance speed and care. Verify changes that could break things.",
  },
  high: {
    maxIterations: 28,
    hint: "Be thorough. Read relevant context before editing, verify your work by running it where possible.",
  },
  max: {
    maxIterations: 50,
    hint: "Be exhaustive. Explore broadly, consider edge cases, verify everything you produce, and double-check results before finishing.",
  },
};

export const GLINT_HOME = join(homedir(), ".glint");
export const DIRS = {
  home: GLINT_HOME,
  logs: join(GLINT_HOME, "logs"),
  diagnostics: join(GLINT_HOME, "diagnostics"),
  sessions: join(GLINT_HOME, "sessions"),
  skills: join(GLINT_HOME, "skills"),
};

export function ensureDirs(): void {
  for (const dir of Object.values(DIRS)) {
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true, mode: 0o700 });
  }
}

export interface UserConfig {
  diagnostics: boolean;
  effort: Effort;
  yolo: boolean;
  intro: boolean;
}

const CONFIG_PATH = join(GLINT_HOME, "config.json");

const DEFAULTS: UserConfig = {
  diagnostics: true,
  effort: "medium",
  yolo: false,
  intro: true,
};

let cached: UserConfig | null = null;

export function loadConfig(): UserConfig {
  if (cached) return cached;
  ensureDirs();
  try {
    const raw = JSON.parse(readFileSync(CONFIG_PATH, "utf8"));
    cached = { ...DEFAULTS, ...raw };
  } catch {
    cached = { ...DEFAULTS };
  }
  return cached!;
}

export function saveConfig(patch: Partial<UserConfig>): UserConfig {
  const next = { ...loadConfig(), ...patch };
  cached = next;
  ensureDirs();
  writeFileSync(CONFIG_PATH, JSON.stringify(next, null, 2) + "\n", { mode: 0o600 });
  return next;
}
